ns.NarrativeTranslations.pl[8727] = "Farwhisper szuka w gwiazdach odpowiedzi na ziemskie tajemnice. Odwiedziny u starszego to okazja, by wysłuchać tej refleksji o poszukiwaniu prawdy."
ns.NarrativeTranslations.pl[8728] = "Narain uważa, że potrafi zbudować opisaną w księdze boję z Arcanite. Kłopot w tym, że najpierw trzeba zebrać potrzebne do budowy rzadkie metale i klejnoty."
ns.NarrativeTranslations.pl[8729] = "Boję trzeba wrzucić do wody w pobliżu wiru w Bay of Storms. Narain ostrzega przed Mawsem, olbrzymim stworem, przez którego odzyskanie odłamka to zadanie dla kilku sojuszników."
ns.NarrativeTranslations.pl[8730] = "Vaelastrasz nie strzeże już odłamka: Nefarius go zabrał i zamierza zniszczyć. Po tym ostrzeżeniu poszukiwania zmieniają się w wyścig o ocalenie tej części berła."
ns.NarrativeTranslations.pl[8731] = "Zanim dostaniesz bardziej złożone zadania, musisz odbyć służbę z oddziałem Orgrimmar Legion. Trzeba zdobyć potwierdzenie udziału i nie zaogniać przy tym stosunków z ochotnikami Przymierza."
ns.NarrativeTranslations.pl[8732] = "Służba polowa ma swoje formalności: trzeba przedstawić kapitanowi dokumenty. Kapitan reaguje zdziwieniem, ale spotkanie z nim jest konieczne, by dostać potwierdzenie twojej służby u boku jego oddziałów."
ns.NarrativeTranslations.pl[8733] = "Malfurion chce, by oczyścić Eranikusa ze skażenia Old Gods i odzyskać zielony odłamek. Agent w pobliżu Darnassus może powiadomić Tyrande, nie alarmując Staghelma."
ns.NarrativeTranslations.pl[8734] = "Tyrande dowie się o planie Malfuriona. Remulos w Moonglade wie, co robić dalej, by przywołać Eranikusa i nadal starać się o jego odkupienie."
ns.NarrativeTranslations.pl[8735] = "Remulos przygotowuje się do przywołania Eranikusa i potrzebuje fragmentów skażenia Nightmare z czterech portali snu. Smocze stwory, które żyją wokół nich, mają próbki potrzebne do tych przygotowań."
ns.NarrativeTranslations.pl[8736] = "Celem jest odkupienie Eranikusa, więc nie wolno go zabić. Gdy Tyrande zmierza z pomocą, twoi sojusznicy muszą wytrzymać jego ataki i obronić Nighthaven."
ns.NarrativeTranslations.pl[8737] = "Kult Twilight's Hammer i jego żywiołaki wysokiej rangi zagrażają działaniom w Silithus. Walki w Ahn'Qiraj to nie powód, by lekceważyć to zagrożenie na zewnątrz, a celem tego zadania jest templariusz Azure Templar."
ns.NarrativeTranslations.pl[8738] = "Landion od wielu dni obserwuje ruchy w Hive'Regal. Gdy zdobędziesz jego pisemny raport, będzie można szybko zareagować na informacje zebrane przez zwiadowcę wysłanego do uli."
ns.NarrativeTranslations.pl[8739] = "Jalia od kilku dni obserwuje ruchy w Hive'Ashi. Jej pisemny raport jest potrzebny, by zamienić te obserwacje w informacje, na które siły w Silithus będą mogły szybko zareagować."
ns.NarrativeTranslations.pl[8740] = "Konni kultyści Twilight napadają na karawany i małe patrole poza zasięgiem Cenarion Hold. Pokonanie ich oraz Morny ma powstrzymać napady, które zagrażają ruchom tamtejszych wojsk."
ns.NarrativeTranslations.pl[8741] = "Zielony odłamek można już zanieść Anachronosowi w Caverns of Time. Strażnik jaskiń czeka na ten fragment, bo to część pracy nad odzyskaniem berła."
ns.NarrativeTranslations.pl[8742] = "Anachronos widzi w twoim przybyciu szansę, by przeciwstawić się przepowiedni C'Thuna. Gdy potwierdzisz swoją gotowość, zaoferuje ci berło Scepter of the Shifting Sands, które pozwoli kontynuować to przedsięwzięcie."
ns.NarrativeTranslations.pl[8743] = "Uderzenie w gong otworzy bramy Ahn'Qiraj i wystawi twój lud na chaos, który się za nimi kryje. To starcie wymaga gotowości, by bronić go przed skutkami otwarcia bram."
ns.NarrativeTranslations.pl[8744] = "Starannie zapakowany prezent z twoim imieniem czeka na odbiór. Zimowe święto przynosi małe odświętne spotkanie, w którym chodzi o to, by odebrać prezent i wspólnie cieszyć się świąteczną atmosferą."
ns.NarrativeTranslations.pl[8745] = "Jonathan pilnuje gongu i czuwa w imieniu Bronze Flight. Timeless One pozwolił mu zaoferować ci przedmiot ze swojego skarbca, by pomóc w bitwach z C'Thunem."
ns.NarrativeTranslations.pl[8746] = "Ktoś porwał Metzena, jednego z reniferów Great-father Wintera, a okupu żądają dwie grupy. Ich listy mogą naprowadzić na trop, a specjalny proszek uwolni go z więzów."
ns.NarrativeTranslations.pl[8747] = "Oddanie sprawie Bronze Flight pozwala ci wybrać ścieżkę obronną. Oferowany pierścień ma lepiej chronić cię przed złem i jest wyrazem uznania za zdobytą przychylność."
ns.NarrativeTranslations.pl[8748] = "Doceniono to, że wciąż bronisz ludów Kalimdor. Gdy oddasz pierścień, będzie można zwiększyć jego moc w uznaniu twojej czujności wobec zagrożeń dla mieszkańców."
ns.NarrativeTranslations.pl[8749] = "Obrona Kalimdor przed tymi, którzy pustoszą jego ziemie, przyniosła ci kolejne wyrazy uznania. Pierścień może znów zyskać na mocy, by wspierać walkę z tymi wrogami."
ns.NarrativeTranslations.pl[8750] = "Twoje czuwanie nad światem dowiodło determinacji godnej nagrody. Pierścień może otrzymać silniejsze zaklęcie w uznaniu tego wytrwałego oddania."
ns.NarrativeTranslations.pl[8751] = "Twoja wytrwałość zasługuje na ostatnie zaklęcie, którego udziela Bronze Flight. Pierścień zostaje wzmocniony na prośbę samego Timeless One, w uznaniu twojej służby."
ns.NarrativeTranslations.pl[8752] = "Bronze Flight docenia twoje starania i proponuje ścieżkę zdobywcy. Jej pierścień wzmacnia ataki fizyczne i nadaje zdobytej u smoków przychylności konkretny kierunek."
ns.NarrativeTranslations.pl[8753] = "Doceniono to, że wciąż bronisz ludów Kalimdor. Gdy oddasz pierścień, będzie można zwiększyć jego moc w uznaniu twojej czujności wobec zagrożeń dla mieszkańców."
ns.NarrativeTranslations.pl[8754] = "Obrona Kalimdor przed tymi, którzy pustoszą jego ziemie, przyniosła ci kolejne wyrazy uznania. Pierścień może znów zyskać na mocy, by wspierać walkę z tymi wrogami."
ns.NarrativeTranslations.pl[8755] = "Twoje czuwanie nad światem dowiodło determinacji godnej nagrody. Pierścień może otrzymać silniejsze zaklęcie w uznaniu tego wytrwałego oddania."
ns.NarrativeTranslations.pl[8756] = "Twoja wytrwałość zasługuje na ostatnie zaklęcie, którego udziela Bronze Flight. Pierścień zostaje wzmocniony na prośbę samego Timeless One, w uznaniu twojej służby."
ns.NarrativeTranslations.pl[8757] = "Starania o przychylność Bronze Flight pozwalają ci wybrać ścieżkę przywoływacza. Oferowany pierścień wzmacnia magiczne i naturalne zdolności tego, kto go nosi."
ns.NarrativeTranslations.pl[8758] = "Doceniono to, że wciąż bronisz ludów Kalimdor. Gdy oddasz pierścień, będzie można zwiększyć jego moc w uznaniu twojej czujności wobec zagrożeń dla mieszkańców."
ns.NarrativeTranslations.pl[8759] = "Obrona Kalimdor przed tymi, którzy pustoszą jego ziemie, przyniosła ci kolejne wyrazy uznania. Pierścień może znów zyskać na mocy, by wspierać walkę z tymi wrogami."
ns.NarrativeTranslations.pl[8760] = "Twoje czuwanie nad światem dowiodło determinacji godnej nagrody. Pierścień może otrzymać silniejsze zaklęcie w uznaniu tego wytrwałego oddania."
ns.NarrativeTranslations.pl[8761] = "Twoja wytrwałość zasługuje na ostatnie zaklęcie, którego udziela Bronze Flight. Pierścień zostaje wzmocniony na prośbę samego Timeless One, w uznaniu twojej służby."
ns.NarrativeTranslations.pl[8762] = "W okresie świątecznym porwano Metzena, a do Smokywood przyszły dwa żądania okupu. Zbadanie listów i użycie uwalniającego proszku to szansa na uratowanie renifera."
ns.NarrativeTranslations.pl[8763] = "Świeży ostrokrzew się psuje, ale maszyna potrafi zakonserwować go na zawsze. Mogą z niej skorzystać wprawni kucharze, którzy przyniosą sól Deeprock i zapłatę za własny trwały zapas."
ns.NarrativeTranslations.pl[8764] = "Żeby zmienić ścieżkę, trzeba oddać swój sygnet i dużo skarabeuszy qiraji. Ta oferta pozwala przemyśleć wybór na nowo, a płaci się materiałami zdobytymi na wrogach z Ahn'Qiraj."
ns.NarrativeTranslations.pl[8765] = "Żeby zmienić ścieżkę, trzeba oddać swój sygnet i dużo skarabeuszy qiraji. Ta oferta pozwala przemyśleć wybór na nowo, a płaci się materiałami zdobytymi na wrogach z Ahn'Qiraj."
ns.NarrativeTranslations.pl[8766] = "Żeby zmienić ścieżkę, trzeba oddać swój sygnet i dużo skarabeuszy qiraji. Ta oferta pozwala przemyśleć wybór na nowo, a płaci się materiałami zdobytymi na wrogach z Ahn'Qiraj."
ns.NarrativeTranslations.pl[8767] = "Prezent, którym chyba ktoś potrząsał, jest zaadresowany specjalnie do ciebie. Podchodząc do paczki, bierzesz udział w tym świątecznym obdarowywaniu, choć nie wiesz z góry, co kryje się pod opakowaniem."
ns.NarrativeTranslations.pl[8768] = "Wśród świątecznych prezentów leży kolorowo zapakowana paczka z twoim imieniem. Coś się chyba w niej rusza, ale żeby odkryć, co dla ciebie przygotowano, trzeba najpierw do niej podejść."
ns.NarrativeTranslations.pl[8769] = "Smokeywood Pastures ma dla ciebie prezent z życzeniami radosnych zimowych świąt. Odbierz upominek przygotowany na święto Feast of Great-Winter."
ns.NarrativeTranslations.pl[8770] = "Obecność silithidów coraz bardziej zagraża działaniom wojennym. Podczas szturmu na Hive'Ashi masz zmierzyć się z broniącymi go silithidami Defender, a potem zdać z tego raport Commander Mar'alithowi."
ns.NarrativeTranslations.pl[8771] = "Silithidy są coraz większym zagrożeniem dla działań wojennych. Mar'alith zleca atak na silithidy Sandstalker z Hive'Ashi, by wesprzeć zorganizowany szturm na siły tego właśnie ula."
ns.NarrativeTranslations.pl[8772] = "Do szturmu na Hive'Zora potrzeba kolejnych posiłków. Twoim celem są tamtejsze silithidy Waywatcher; to wsparcie dla ofensywy sił, którymi Mar'alith dowodzi z Cenarion Hold."
ns.NarrativeTranslations.pl[8773] = "Trwa szturm na Hive'Zora i potrzeba posiłków, by kontynuować ofensywę. Walka z tamtejszymi silithidami Reaver to konkretne zadanie od Mar'alitha, część szerszych działań przeciw ulowi."
ns.NarrativeTranslations.pl[8774] = "Zagrożenie ze strony silithidów rośnie wraz z postępami działań wojennych. Atak na silithidy Ambusher z Hive'Regal jest częścią ofensywy, którą Mar'alith chce osłonić działania swoich sił."
ns.NarrativeTranslations.pl[8775] = "Siły silithidów zagrażają działaniom wojennym. Celem tego szturmu na Hive'Regal są latające silithidy Spitfire, a o wyniku trzeba potem zameldować Mar'alithowi w Cenarion Hold."
ns.NarrativeTranslations.pl[8776] = "Rosnące zagrożenie ze strony silithidów wymaga uderzenia na Hive'Regal. Wyznaczonym celem są tamtejsze silithidy Slavemaker, a ofensywa ma zmniejszyć niebezpieczeństwo grożące działaniom wojennym."
ns.NarrativeTranslations.pl[8777] = "Szturm na Hive'Regal to odpowiedź na rosnące niebezpieczeństwo ze strony silithidów. Mar'alith zleca ci walkę z tamtejszymi silithidami Burrower w ramach tej operacji przeciw ulowi."
ns.NarrativeTranslations.pl[8778] = "Oddział Ironforge Brigade prosi o wyjątkowo niestabilne składniki. Zbierając je i zanosząc Nozzlespringowi, spełniasz nietypową prośbę o zaopatrzenie od sił tego oddziału w Silithus."
ns.NarrativeTranslations.pl[8779] = "Badania Larksbane są cenne dla działań w Silithus, ale wymagają materiałów do jasnowidzenia. Gdy je zbierzesz i dostarczysz geolożce, będzie mogła dalej prowadzić badania dla Cenarion Hold."
ns.NarrativeTranslations.pl[8780] = "Oddziałowi Ironforge Brigade niebezpiecznie kończą się w polu zestawy do pancerzy. Janela potrzebuje kolejnej dostawy w placówce przy Hive'Zora, by żołnierze oddziału w terenie mieli sprawny sprzęt."
ns.NarrativeTranslations.pl[8781] = "Oddział Ironforge Brigade pomógł w Silithus, ale po drodze stracił dużo zapasów. Broń zaniesiona Janeli zastąpi część sprzętu, którego ci sojusznicy potrzebują."
ns.NarrativeTranslations.pl[8782] = "Po przybyciu kolejnych ochotników skończyły się zapasy mundurów. Proudhorn potrzebuje materiałów, by je uzupełnić i wyposażyć nowych pomocników, którzy dołączają do sił Cenarion Hold."
ns.NarrativeTranslations.pl[8783] = "Vargus potrzebuje zaklętych materiałów, by wykuć potężną broń dla sił Cenarion Hold. Dostarczając je prosto kowalowi, pomagasz dbać o to, by te oddziały były dobrze wyposażone."
ns.NarrativeTranslations.pl[8784] = "W twoje ręce trafił starożytny artefakt qiraji i nie wiadomo jeszcze, czy jest coś wart. Smoki przy wejściu do świątyni mogą wiedzieć, do czego przyda się odzyskana relikwia."
ns.NarrativeTranslations.pl[8785] = "Oddział Orgrimmar Legion dobrze spisuje się w Silithus, co zachęca, by szybko odpowiedzieć na jego prośbę. Shai czeka na kilka nietypowych składników, których wymaga to zadanie zaopatrzeniowe."
ns.NarrativeTranslations.pl[8786] = "Oddział Orgrimmar Legion potrzebuje dodatkowej broni, której dotąd mu nie dostarczono. Zanosząc ją Merokowi w pobliżu Hive'Regal, uzupełniasz braki w wyposażeniu oddziału."
ns.NarrativeTranslations.pl[8787] = "Ochotnicy z Orgrimmar Legion dotarli do Silithus, ale ich zestawy do pancerzy przepadły w drodze. Merok potrzebuje nowych dla obozu, który wspiera sprawę Cenarion."
ns.NarrativeTranslations.pl[8788] = "Prezent, którym chyba ktoś potrząsał, jest zaadresowany specjalnie do ciebie. Podchodząc do paczki, bierzesz udział w tym świątecznym obdarowywaniu, choć nie wiesz z góry, co kryje się pod opakowaniem."
ns.NarrativeTranslations.pl[8789] = "Smoki od stuleci obserwują okrucieństwo i słabości qiraji. Ceremonialną broń tych istot można połączyć z pierwiastkiem zrodzonym z niestabilności ich boga i obrócić przeciwko nim."
ns.NarrativeTranslations.pl[8790] = "Arygos uważa, że Elementium może być zabójcze dla Old Gods i ich sług. Połączone z cesarskimi regaliami qiraji mogłoby nasycić broń mocą, wykorzystując tę słabość."
ns.NarrativeTranslations.pl[8791] = "Ossirian padł, a ta wiadomość może uspokoić mieszkańców Kalimdor. Zanosząc jego głowę Mar'alithowi, meldujesz o zwycięstwie i dajesz dowód, że zagrożenia już nie ma."
ns.NarrativeTranslations.pl[8792] = "Horda potrzebuje pomocy przy zbieraniu zasobów na kampanię w Ahn'Qiraj. Gorchuk kieruje przygotowaniami i doradzi każdemu, kto chce pomóc oficjalnym zbieraczom."
ns.NarrativeTranslations.pl[8793] = "Horda potrzebuje pomocy przy zbieraniu zasobów na kampanię w Ahn'Qiraj. Gorchuk kieruje przygotowaniami i doradzi każdemu, kto chce pomóc oficjalnym zbieraczom."
ns.NarrativeTranslations.pl[8794] = "Horda potrzebuje pomocy przy zbieraniu zasobów na kampanię w Ahn'Qiraj. Gorchuk kieruje przygotowaniami i doradzi każdemu, kto chce pomóc oficjalnym zbieraczom."
ns.NarrativeTranslations.pl[8795] = "Oficjalni zbieracze Przymierza sami nie zgromadzą zasobów na Ahn'Qiraj. Snowfall koordynuje przygotowania i potrzebuje ochotników, którzy pomogą osiągnąć cele wysiłku wojennego."
ns.NarrativeTranslations.pl[8796] = "Oficjalni zbieracze Przymierza sami nie zgromadzą zasobów na Ahn'Qiraj. Snowfall koordynuje przygotowania i potrzebuje ochotników, którzy pomogą osiągnąć cele wysiłku wojennego."
ns.NarrativeTranslations.pl[8797] = "Oficjalni zbieracze Przymierza sami nie zgromadzą zasobów na Ahn'Qiraj. Snowfall koordynuje przygotowania i potrzebuje ochotników, którzy pomogą osiągnąć cele wysiłku wojennego."
ns.NarrativeTranslations.pl[8798] = "Twoja pomoc przynosi propozycję: możesz nauczyć się budować mechanicznego yeti. Dzięki znajomości inżynierii skorzystasz z tej lekcji, choć do budowy trzeba jeszcze zebrać części."
ns.NarrativeTranslations.pl[8799] = "Świeży ostrokrzew się psuje, ale maszyna potrafi zakonserwować go na zawsze. Mogą z niej skorzystać wprawni kucharze, którzy przyniosą sól Deeprock i zapłatę za własny trwały zapas."
ns.NarrativeTranslations.pl[8800] = "Odznaki zdobyte za wojenne zadania pokazują Vargusowi twoje zaangażowanie. Rozmowa z kowalem daje dostęp do wyposażenia, które Cenarion Hold przydziela zależnie od odbytej służby."
ns.NarrativeTranslations.pl[8801] = "Szczątki C'Thuna nawet po jego unicestwieniu promieniują niepokojącym złem. Zanosząc smokom jedno z jego oczu, pokazujesz znalezisko tym, którzy czekają w następnej komnacie."
ns.NarrativeTranslations.pl[8802] = "Anachronos czeka na oko C'Thuna w Caverns of Time. Dostarczając ten dowód zwycięstwa, przekazujesz go do kolekcji skarbów jego pana."
ns.NarrativeTranslations.pl[8803] = "Do świątecznego prezentu dołączone są dobre życzenia od Greatfather Wintera. Odebranie go to część święta, które zachęca, by nieść ciepło i świąteczną radość innym mieszkańcom świata Azeroth."
ns.NarrativeTranslations.pl[8804] = "Nowi rekruci w Cenarion Hold nie znają niebezpieczeństw pustyni. Calandrath potrzebuje zapasów na zestawy przetrwania, które chronią przed odwodnieniem i licznymi jadowitymi stworzeniami zagrażającymi niedoświadczonym ochotnikom."
ns.NarrativeTranslations.pl[8805] = "Konni strażnicy z Cenarion Hold potrzebują zdobionych butów z Mithril. Pilna dostawa dla Visha Kozusa, jedno z zadań zaopatrzeniowych, uzupełnia ten brak w wyposażeniu."
ns.NarrativeTranslations.pl[8806] = "Strażnikom z Cenarion Hold brakuje kamieni szlifierskich. Dostarczając ich partię Vishowi Kozusowi, uzupełniasz zapasy zamówione dla sił pod jego dowództwem."
ns.NarrativeTranslations.pl[8807] = "Badania Larksbane są cenne dla działań w Silithus, ale wymagają materiałów do jasnowidzenia. Gdy je zbierzesz i dostarczysz geolożce, będzie mogła dalej prowadzić badania dla Cenarion Hold."
ns.NarrativeTranslations.pl[8808] = "Po przybyciu kolejnych ochotników skończyły się zapasy mundurów. Proudhorn potrzebuje materiałów, by je uzupełnić i wyposażyć nowych pomocników, którzy dołączają do sił Cenarion Hold."
ns.NarrativeTranslations.pl[8809] = "Vargus potrzebuje zaklętych materiałów, by wykuć potężną broń dla sił Cenarion Hold. Dostarczając je prosto kowalowi, pomagasz dbać o to, by te oddziały były dobrze wyposażone."
ns.NarrativeTranslations.pl[8810] = "Po ostatnich stratach zapasy bandaży w polu niebezpiecznie się skurczyły. Proudhorn potrzebuje materiałów opatrunkowych, by uzupełnić zapas, z którego korzystają siły Cenarion Hold."
ns.NarrativeTranslations.pl[8811] = "Darnassus przyjmuje pojedynczy sygnet Commendation Signet od tych, którzy nie mają jeszcze dziesięciu. Taki dar przynosi mniej uznania, ale pozwala docenić także mniejsze zasługi dla miasta."
ns.NarrativeTranslations.pl[8812] = "Gnomy z Gnomeregan Exiles przyznają skromne uznanie za pojedynczy sygnet Commendation Signet. Oddawanie sygnetów pojedynczo jest dla tych, którzy nie mogą jeszcze zebrać dziesięciu potrzebnych do większego uznania zasług."
ns.NarrativeTranslations.pl[8813] = "Ironforge pozwala oddać jeden sygnet Commendation Signet tym, którzy nie mają dziesięciu. W ten sposób docenia się mniejsze dary, choć zebranie pełnego kompletu przyniosłoby większe uznanie dla twoich starań."
ns.NarrativeTranslations.pl[8814] = "Stormwind także docenia zasługi, których dowodem jest pojedynczy sygnet Commendation Signet. Taki dar przynosi mniej uznania niż dziesięć naraz, ale pozwala wziąć udział tym, którzy nie mają kompletu."
ns.NarrativeTranslations.pl[8815] = "Orgrimmar pozwala oddać pojedynczy sygnet Commendation Signet tym, którzy nie mają dziesięciu. Daje to skromne uznanie i zachęca do większych darów, za które zasługi docenia się wyżej."
ns.NarrativeTranslations.pl[8816] = "Trolle Darkspear pozwalają potwierdzić zasługi pojedynczym sygnetem Commendation Signet. Przynosi on skromne uznanie, a wyżej cenione pozostają dary po dziesięć sztuk."
ns.NarrativeTranslations.pl[8817] = "Undercity przyjmuje jeden sygnet Commendation Signet, by docenić zasługi tych, którzy nie mają dziesięciu. Ta możliwość daje mniej uznania, ale pozwala uwzględnić dary zbyt małe na pełną dostawę."
ns.NarrativeTranslations.pl[8818] = "Thunder Bluff przyjmuje pojedyncze sygnety Commendation Signet, by docenić mniejsze zasługi. Kto nie ma dziesięciu, może oddać jeden, choć pełny komplet przyniósłby większe uznanie dla jego starań."
ns.NarrativeTranslations.pl[8819] = "Darnassus docenia zasługi potwierdzone sygnetami Commendation Signet. Oddanie dziesięciu naraz przynosi większe uznanie niż pojedyncze dary, choć mniejsze zasługi też są doceniane."
ns.NarrativeTranslations.pl[8820] = "Gnomy z Gnomeregan Exiles przyjmują sygnety Commendation Signet jako dowód służby. Za dziesięć oddanych naraz ich przedstawiciel przyznaje większe uznanie, ale przyjmuje też pojedyncze sygnety, by docenić mniejsze dary."
ns.NarrativeTranslations.pl[8821] = "Ironforge przyjmuje sygnety Commendation Signet jako dowód służby. Dziesięć oddanych za jednym razem przynosi większe uznanie niż wręczanie ich pojedynczo przedstawicielowi miasta."
ns.NarrativeTranslations.pl[8822] = "Stormwind ceni służbę potwierdzoną sygnetami Commendation Signet. Zebranie dziesięciu przynosi większe uznanie niż oddawanie ich osobno, choć miasto przyjmuje też pojedyncze sygnety."
ns.NarrativeTranslations.pl[8823] = "Orgrimmar nagradza uznaniem służbę potwierdzoną sygnetami Commendation Signet. Przedstawiciel miasta woli dostawać je po dziesięć, ale przyjmuje też pojedyncze dary, by żadna zasługa nie została pominięta."
ns.NarrativeTranslations.pl[8824] = "Plemię Darkspear docenia służbę potwierdzoną sygnetami Commendation Signet. Dziesięć sygnetów przynosi większe uznanie niż jeden, choć plemię przyjmuje dary w obu postaciach."
ns.NarrativeTranslations.pl[8825] = "Thunder Bluff okazuje uznanie tym, którzy przynoszą sygnety Commendation Signet otrzymane za służbę. Dziesięć naraz ma większą wartość niż pojedyncze sygnety, ale żaden dar nie zostaje odrzucony."
ns.NarrativeTranslations.pl[8826] = "Undercity przyjmuje sygnety Commendation Signet jako dowód służby. Dziesięć oddanych naraz przynosi większe uznanie niż oddawane pojedynczo, choć i w ten sposób miasto docenia mniejsze dary."
ns.NarrativeTranslations.pl[8827] = "Greatfather Winter zostawił prezenty pod choinką w Ironforge przy wsparciu pewnej świątecznej firmy. Operator zachęca cię do odwiedzin, a sam zostaje przy świątecznej maszynie, którą się zajmuje."
ns.NarrativeTranslations.pl[8828] = "Prezenty od Great-father Wintera czekają pod choinką w Orgrimmar. Operator świątecznej maszyny nie może opuścić stanowiska, ale zachęca cię, żeby tam zajrzeć i wziąć udział w trwającym święcie."
ns.NarrativeTranslations.pl[8829] = "Tajemnice kultu Twilight's Hammer prowadzą najwyraźniej do miejsca, do którego nie ma dostępu. Aurel potrzebuje wiernej kopii szaty emisariusza, by spróbować dostać się do środka przez kamienie przywołań kultu."
ns.NarrativeTranslations.pl[8830] = "Darnassus przyjmuje pojedynczy sygnet Commendation Signet od tych, którzy nie mają jeszcze dziesięciu. Taki dar przynosi mniej uznania, ale pozwala docenić także mniejsze zasługi dla miasta."
ns.NarrativeTranslations.pl[8831] = "Darnassus docenia zasługi potwierdzone sygnetami Commendation Signet. Oddanie dziesięciu naraz przynosi większe uznanie niż pojedyncze dary, choć mniejsze zasługi też są doceniane."
ns.NarrativeTranslations.pl[8832] = "Undercity przyjmuje jeden sygnet Commendation Signet, by docenić zasługi tych, którzy nie mają dziesięciu. Ta możliwość daje mniej uznania, ale pozwala uwzględnić dary zbyt małe na pełną dostawę."
ns.NarrativeTranslations.pl[8833] = "Undercity przyjmuje sygnety Commendation Signet jako dowód służby. Dziesięć oddanych naraz przynosi większe uznanie niż oddawane pojedynczo, choć i w ten sposób miasto docenia mniejsze dary."
ns.NarrativeTranslations.pl[8834] = "Ironforge pozwala oddać jeden sygnet Commendation Signet tym, którzy nie mają dziesięciu. W ten sposób docenia się mniejsze dary, choć zebranie pełnego kompletu przyniosłoby większe uznanie dla twoich starań."
ns.NarrativeTranslations.pl[8835] = "Ironforge przyjmuje sygnety Commendation Signet jako dowód służby. Dziesięć oddanych za jednym razem przynosi większe uznanie niż wręczanie ich pojedynczo przedstawicielowi miasta."
ns.NarrativeTranslations.pl[8836] = "Stormwind także docenia zasługi, których dowodem jest pojedynczy sygnet Commendation Signet. Taki dar przynosi mniej uznania niż dziesięć naraz, ale pozwala wziąć udział tym, którzy nie mają kompletu."
ns.NarrativeTranslations.pl[8837] = "Stormwind ceni służbę potwierdzoną sygnetami Commendation Signet. Zebranie dziesięciu przynosi większe uznanie niż oddawanie ich osobno, choć miasto przyjmuje też pojedyncze sygnety."
ns.NarrativeTranslations.pl[8838] = "Gnomy z Gnomeregan Exiles przyznają skromne uznanie za pojedynczy sygnet Commendation Signet. Oddawanie sygnetów pojedynczo jest dla tych, którzy nie mogą jeszcze zebrać dziesięciu potrzebnych do większego uznania zasług."
ns.NarrativeTranslations.pl[8839] = "Gnomy z Gnomeregan Exiles przyjmują sygnety Commendation Signet jako dowód służby. Za dziesięć oddanych naraz ich przedstawiciel przyznaje większe uznanie, ale przyjmuje też pojedyncze sygnety, by docenić mniejsze dary."
ns.NarrativeTranslations.pl[8840] = "Orgrimmar pozwala oddać pojedynczy sygnet Commendation Signet tym, którzy nie mają dziesięciu. Daje to skromne uznanie i zachęca do większych darów, za które zasługi docenia się wyżej."
ns.NarrativeTranslations.pl[8841] = "Orgrimmar nagradza uznaniem służbę potwierdzoną sygnetami Commendation Signet. Przedstawiciel miasta woli dostawać je po dziesięć, ale przyjmuje też pojedyncze dary, by żadna zasługa nie została pominięta."
ns.NarrativeTranslations.pl[8842] = "Thunder Bluff przyjmuje pojedyncze sygnety Commendation Signet, by docenić mniejsze zasługi. Kto nie ma dziesięciu, może oddać jeden, choć pełny komplet przyniósłby większe uznanie dla jego starań."
ns.NarrativeTranslations.pl[8843] = "Thunder Bluff okazuje uznanie tym, którzy przynoszą sygnety Commendation Signet otrzymane za służbę. Dziesięć naraz ma większą wartość niż pojedyncze sygnety, ale żaden dar nie zostaje odrzucony."
ns.NarrativeTranslations.pl[8844] = "Trolle Darkspear pozwalają potwierdzić zasługi pojedynczym sygnetem Commendation Signet. Przynosi on skromne uznanie, a wyżej cenione pozostają dary po dziesięć sztuk."
ns.NarrativeTranslations.pl[8845] = "Plemię Darkspear docenia służbę potwierdzoną sygnetami Commendation Signet. Dziesięć sygnetów przynosi większe uznanie niż jeden, choć plemię przyjmuje dary w obu postaciach."
ns.NarrativeTranslations.pl[8846] = "Sygnety Commendation Signet można wymienić na zapasy wojenne dla siebie. W tej ofercie chodzi o sprzęt, który pomoże przetrwać bitwę, a nie o uznanie za oddanie zdobytych sygnetów."
ns.NarrativeTranslations.pl[8847] = "Sygnety Commendation Signet można wymienić na zapasy wojenne dla siebie. Rezygnujesz wtedy z uznania za te sygnety, a w zamian dostajesz sprzęt, który może pomóc ci przetrwać, gdy dojdzie do bitwy."
ns.NarrativeTranslations.pl[8848] = "Sygnety Commendation Signet można też wymienić na zapasy wojenne dla siebie. Taki układ daje sprzęt, który może pomóc przetrwać bitwę, kosztem uznania, jakie przyniosłoby oddanie sygnetów w inny sposób."
ns.NarrativeTranslations.pl[8849] = "Przed zbliżającą się bitwą dodatkowe zapasy są cenne. Sygnety Commendation Signet możesz wymienić na sprzęt, który pomoże przetrwać, choć wydane w ten sposób nie przynoszą uznania za służbę."
ns.NarrativeTranslations.pl[8850] = "Przed zbliżającą się bitwą dodatkowe zapasy są cenne. Sygnety Commendation Signet możesz wymienić na sprzęt, który pomoże przetrwać, choć wydane w ten sposób nie przynoszą uznania za służbę."
ns.NarrativeTranslations.pl[8851] = "Sygnety Commendation Signet można wymienić na zapasy wojenne dla siebie. W tej ofercie chodzi o sprzęt, który pomoże przetrwać bitwę, a nie o uznanie za oddanie zdobytych sygnetów."
ns.NarrativeTranslations.pl[8852] = "Ponieważ potrzeba więcej sprzętu, sygnety Commendation Signet można wymieniać na zapasy. Oddane w ten sposób nie przynoszą uznania, ale zdobyte przedmioty mogą lepiej przygotować cię do wojny."
ns.NarrativeTranslations.pl[8853] = "Ponieważ potrzeba więcej materiałów, sygnety można wymieniać na zapasy wojenne. Oddane w ten sposób nie przynoszą uznania, ale ich wartość może zamienić się w sprzęt, który lepiej przygotuje cię do walki."
ns.NarrativeTranslations.pl[8854] = "Przed zbliżającą się bitwą dodatkowe zapasy są cenne. Sygnety Commendation Signet możesz wymienić na sprzęt, który pomoże przetrwać, choć wydane w ten sposób nie przynoszą uznania za służbę."
ns.NarrativeTranslations.pl[8855] = "Przed zbliżającą się bitwą dodatkowe zapasy są cenne. Sygnety Commendation Signet możesz wymienić na sprzęt, który pomoże przetrwać, choć wydane w ten sposób nie przynoszą uznania za służbę."
ns.NarrativeTranslations.pl[8856] = "Nowi rekruci w Cenarion Hold nie znają niebezpieczeństw pustyni. Calandrath potrzebuje zapasów na zestawy przetrwania, które chronią przed odwodnieniem i licznymi jadowitymi stworzeniami zagrażającymi niedoświadczonym ochotnikom."
ns.NarrativeTranslations.pl[8857] = "Oglethorpe potrzebuje świeżej próbki z powalonego kolosa Ashi. Trudność nie polega już na jej pobraniu, tylko na tym, by szybko dowieźć gotową próbkę, zanim zgnije."
ns.NarrativeTranslations.pl[8858] = "Zbieracz ma pełne ręce roboty przy pobieraniu próbek z kolosa Regal. Oilfist płaci za świeże próbki, więc potrzebny jest szybki posłaniec, który dostarczy jedną do Searing Gorge."
ns.NarrativeTranslations.pl[8859] = "Maxwell Tyrosus uważa, że kolos Zora może kryć tajemnice przydatne w walce ze Scourge. Próbka zdobyta ze sporym ryzykiem musi dotrzeć do Light's Hope Chapel, póki jest świeża."
ns.NarrativeTranslations.pl[8860] = "Na noworoczne obchody w Stormwind potrzeba jedzenia dla gości. Allison czeka w swojej karczmie na dostawę przysmaków Smokywood Pastures, by nakarmić uczestników zabawy."
ns.NarrativeTranslations.pl[8861] = "Pala musi zaopatrzyć swoją karczmę na noworoczne obchody w Thunder Bluff. Dostawa jedzenia Smokywood Pastures pomoże nakarmić gości, którzy przyjdą na miejskie święto."
ns.NarrativeTranslations.pl[8862] = "Świeca Elune's Candle kryje w sobie prawdziwe światło księżyca, czczone podczas Lunar Festival. Większości stworzeń nie szkodzi, ale jej blask potrafi poparzyć i oślepić Omena i jego sługi."
ns.NarrativeTranslations.pl[8863] = "Pierożki należą do tradycji Lunar Festival od pierwszych obchodów. Za monetę Coin of Ancestry możesz ich spróbować w ramach wymiany dostępnej dla tych, którzy oddają cześć starszym."
ns.NarrativeTranslations.pl[8864] = "Suknie na Lunar Festival zachowują kroje noszone podczas dawnych obchodów. Za monety Coin of Ancestry możesz wybrać ręcznie szyty strój i dołączyć do tej tradycji we własnym ubraniu."
ns.NarrativeTranslations.pl[8865] = "Kostiumy ze spodniami to odświętne stroje szyte specjalnie na tę okazję. Za monety Coin of Ancestry możesz wybrać jeden z dostępnych krojów i nosić go podczas obchodów."
ns.NarrativeTranslations.pl[8866] = "Bronzebeard cieszy się, że dawnym ludom tych ziem wciąż oddaje się cześć. Przy spotkaniu odwdzięcza się za ten szacunek znakiem uznania dla kogoś, kto podtrzymuje pamięć o nich."
ns.NarrativeTranslations.pl[8867] = "Druidzi świętują dawne zwycięstwo Moonglade ucztami i fajerwerkami. Kupując rakiety i odpalając je z ich wyrzutni, dołączasz do obchodów ku czci mądrości starszych."
ns.NarrativeTranslations.pl[8868] = "Omen był bohaterem, zanim demoniczna magia obróciła go przeciw sojusznikom. Podczas każdego Lunar Festival znów budzi się w miejscu spoczynku, więc potrzeba towarzyszy gotowych stawić mu czoła."
ns.NarrativeTranslations.pl[8869] = "Żeby szkolić się na kowala młotów, trzeba odzyskać fartuch kowala Scarlet, który strzeże projektu Serenity. Ta próba potwierdza, że wybierasz tę specjalizację zamiast innych ścieżek rzemiosła."
ns.NarrativeTranslations.pl[8870] = "Cenarion Circle zaprasza wszystkich mieszkańców Azeroth na Lunar Festival. Zwiastunka stojąca w kręgu księżycowego światła może opowiedzieć o święcie tym, którzy chcą wziąć w nim udział."
ns.NarrativeTranslations.pl[8871] = "Cenarion Circle zaprasza wszystkich mieszkańców Azeroth na Lunar Festival. Zwiastunka stojąca w kręgu księżycowego światła może opowiedzieć o święcie tym, którzy chcą wziąć w nim udział."
ns.NarrativeTranslations.pl[8872] = "Cenarion Circle zaprasza wszystkich mieszkańców Azeroth na Lunar Festival. Zwiastunka stojąca w kręgu księżycowego światła może opowiedzieć o święcie tym, którzy chcą wziąć w nim udział."
ns.NarrativeTranslations.pl[8873] = "Cenarion Circle zaprasza wszystkich mieszkańców Azeroth na Lunar Festival. Zwiastunka stojąca w kręgu księżycowego światła może opowiedzieć o święcie tym, którzy chcą wziąć w nim udział."
ns.NarrativeTranslations.pl[8874] = "Cenarion Circle zaprasza wszystkich mieszkańców Azeroth na Lunar Festival. Zwiastunka stojąca w kręgu księżycowego światła może opowiedzieć o święcie tym, którzy chcą wziąć w nim udział."
ns.NarrativeTranslations.pl[8875] = "Cenarion Circle zaprasza wszystkich mieszkańców Azeroth na Lunar Festival. Zwiastunka stojąca w kręgu księżycowego światła może opowiedzieć o święcie tym, którzy chcą wziąć w nim udział."
ns.NarrativeTranslations.pl[8876] = "Wiedza o małych rakietach na Lunar Festival trafia do tych, którzy zdobyli uznanie. Za monety Coin of Ancestry możesz poznać receptury i wzbogacić obchody własnymi wyrobami."
ns.NarrativeTranslations.pl[8877] = "Rakiety potrzebują wyrzutni, żeby rozświetlić święto. Za monety Coin of Ancestry możesz nauczyć się budować urządzenia takie jak te w Moonglade i urządzać zabawy z przyjaciółmi."
ns.NarrativeTranslations.pl[8878] = "Tradycyjne suknie i kostiumy to hołd dla dawnych zwyczajów i bliskich, którzy odeszli. Za monety Coin of Ancestry możesz poznać wykroje, z których szyje się te stroje ku pamięci."
ns.NarrativeTranslations.pl[8879] = "Duże rakiety na Lunar Festival rozświetlają niebo blaskiem, któremu dorównują wiązki rakiet. Za monety Coin of Ancestry możesz nauczyć się je budować i dołożyć coś od siebie do świątecznego pokazu."
ns.NarrativeTranslations.pl[8880] = "Wiązki rakiet łączą pojedyncze rakiety we wspólny pokaz. Receptury na nie można dostać za monety Coin of Ancestry, dzięki czemu uczestnicy mogą przygotować na święto własne wyroby."
ns.NarrativeTranslations.pl[8881] = "Duże wiązki rakiet wymagają mnóstwa materiałów i wprawy, ale ich piękno jest warte wysiłku. Monety Coin of Ancestry dają dostęp do wiedzy potrzebnej, by wytwarzać te świąteczne fajerwerki."
ns.NarrativeTranslations.pl[8882] = "Wiązki rakiet potrzebują osobnych wyrzutni, żeby stać się częścią wielkiego pokazu. Za monety Coin of Ancestry możesz nauczyć się budować taki sprzęt na zabawy w duchu Lunar Festival."
ns.NarrativeTranslations.pl[8883] = "Zaproszenie na Lunar Festival pozwala przenieść się do Moonglade przez światło księżyca. Valadar i Fariel witają tych, którzy chcą wziąć udział w święcie i dowiedzieć się o nagrodach."
ns.NarrativeTranslations.pl[8893] = "Super Egg-O-Matic Curgle’a przyjmuje jajo hipogryfa i wydaje za nie skrzynkę jaj. Maszyna prycha obok swojego panelu sterowania, przy którym możesz oddać jajo na wymianę."
ns.NarrativeTranslations.pl[8897] = "Służba na warcie zostawia niewiele czasu na odwiedziny u Colary. Jej adorator boi się, że odbiorą mu ją bogatsi mężczyźni, i prosi cię, żeby zanieść jej to, co dla niej napisał."
ns.NarrativeTranslations.pl[8898] = "Przyjezdny, który odwiedził Stormwind w interesach, zakochał się w Colarze. Wiele razy przepisywał swój list i szuka kogoś, kto doręczy go osobiście, z pominięciem przeciążonej poczty."
ns.NarrativeTranslations.pl[8899] = "Adorator Colary nie potrafi w pełni wyrazić piękna, które w niej widzi. Boi się, że ktoś inny przyciągnie jej uwagę, więc chce, by doręczono list, który poprawiał zbyt długo."
ns.NarrativeTranslations.pl[8900] = "Przez drwiny towarzyszy przestał rozmawiać z Elenią, choć znalazł u niej zrozumienie. Teraz za nią tęskni i chce, by jego list trafił prosto do jej rąk."
ns.NarrativeTranslations.pl[8901] = "Miłość do Elenii zaskakuje kogoś, kto nie przywykł patrzeć poza własny lud. W liście zaprasza młodą kobietę z Undercity do Mulgore i ma nadzieję, że ona się zgodzi."
ns.NarrativeTranslations.pl[8902] = "Po latach rozłąki i zmian dawny narzeczony znów myśli o Elenii. Ma nadzieję, że jest jeszcze miejsce na ich miłość, ale potrzebuje posłańca, bo boi się sam doręczyć list."
ns.NarrativeTranslations.pl[8903] = "Fala zauroczeń wygląda nienaturalnie i może osłabić obronę Przymierza. Sprawdzenie, czy dotknęła też strażników Stormwind, to początek śledztwa w sprawie tych podejrzeń."
ns.NarrativeTranslations.pl[8904] = "Dziwna epidemia miłości może osłabić obronę tych, których dotknęła. Trzeba ustalić, czy ulegli jej nawet strażnicy, choć takie zachowanie uchodziło u nich za niemożliwe."
ns.NarrativeTranslations.pl[8905] = "Wymiana zwykłych karwaszy na lepsze wymaga krwi niedźwiedzi i kotów Frostsaber z Winterspring. Jej właściwości są potrzebne osobie, która proponuje ulepszenie, a do tego dochodzi niewielka opłata."
ns.NarrativeTranslations.pl[8906] = "Wymiana zwykłych karwaszy na lepsze wymaga krwi niedźwiedzi i kotów Frostsaber z Winterspring. Jej właściwości są potrzebne osobie, która proponuje ulepszenie, a do tego dochodzi niewielka opłata."
ns.NarrativeTranslations.pl[8907] = "Wymiana zwykłych karwaszy na lepsze wymaga krwi niedźwiedzi i kotów Frostsaber z Winterspring. Jej właściwości są potrzebne osobie, która proponuje ulepszenie, a do tego dochodzi niewielka opłata."
ns.NarrativeTranslations.pl[8908] = "Wymiana zwykłych karwaszy na lepsze wymaga krwi niedźwiedzi i kotów Frostsaber z Winterspring. Jej właściwości są potrzebne osobie, która proponuje ulepszenie, a do tego dochodzi niewielka opłata."
ns.NarrativeTranslations.pl[8909] = "Wymiana zwykłych karwaszy na lepsze wymaga krwi niedźwiedzi i kotów Frostsaber z Winterspring. Jej właściwości są potrzebne osobie, która proponuje ulepszenie, a do tego dochodzi niewielka opłata."
ns.NarrativeTranslations.pl[8910] = "Wymiana zwykłych karwaszy na lepsze wymaga krwi niedźwiedzi i kotów Frostsaber z Winterspring. Jej właściwości są potrzebne osobie, która proponuje ulepszenie, a do tego dochodzi niewielka opłata."
ns.NarrativeTranslations.pl[8911] = "Wymiana zwykłych karwaszy na lepsze wymaga krwi niedźwiedzi i kotów Frostsaber z Winterspring. Jej właściwości są potrzebne osobie, która proponuje ulepszenie, a do tego dochodzi niewielka opłata."
ns.NarrativeTranslations.pl[8912] = "Wymiana zwykłych karwaszy na lepsze wymaga krwi niedźwiedzi i kotów Frostsaber z Winterspring. Jej właściwości są potrzebne osobie, która proponuje ulepszenie, a do tego dochodzi niewielka opłata."
ns.NarrativeTranslations.pl[8913] = "Pająki i skorpiony z Silithus dają jad potrzebny osobie, która proponuje lepsze karwasze. Spora próbka jadu, zwykłe karwasze i opłata pozwalają na wymianę."
ns.NarrativeTranslations.pl[8914] = "Pająki i skorpiony z Silithus dają jad potrzebny osobie, która proponuje lepsze karwasze. Spora próbka jadu, zwykłe karwasze i opłata pozwalają na wymianę."
ns.NarrativeTranslations.pl[8915] = "Pająki i skorpiony z Silithus dają jad potrzebny osobie, która proponuje lepsze karwasze. Spora próbka jadu, zwykłe karwasze i opłata pozwalają na wymianę."
ns.NarrativeTranslations.pl[8916] = "Pająki i skorpiony z Silithus dają jad potrzebny osobie, która proponuje lepsze karwasze. Spora próbka jadu, zwykłe karwasze i opłata pozwalają na wymianę."
ns.NarrativeTranslations.pl[8917] = "Pająki i skorpiony z Silithus dają jad potrzebny osobie, która proponuje lepsze karwasze. Spora próbka jadu, zwykłe karwasze i opłata pozwalają na wymianę."
ns.NarrativeTranslations.pl[8918] = "Pająki i skorpiony z Silithus dają jad potrzebny osobie, która proponuje lepsze karwasze. Spora próbka jadu, zwykłe karwasze i opłata pozwalają na wymianę."
ns.NarrativeTranslations.pl[8919] = "Pająki i skorpiony z Silithus dają jad potrzebny osobie, która proponuje lepsze karwasze. Spora próbka jadu, zwykłe karwasze i opłata pozwalają na wymianę."
ns.NarrativeTranslations.pl[8920] = "Pająki i skorpiony z Silithus dają jad potrzebny osobie, która proponuje lepsze karwasze. Spora próbka jadu, zwykłe karwasze i opłata pozwalają na wymianę."
ns.NarrativeTranslations.pl[8921] = "Mux musi zbudować destylator, który zbiera widmową materię zmarłych. Brakuje mu na to pieniędzy i rąk do pracy, a na filtr potrzeba magicznych składników, oleju i popiołu wulkanicznego."
ns.NarrativeTranslations.pl[8922] = "Ostatnią nadzieją jest rozmowa z duchem Anthiona. Inżynier z Gadgetzan twierdzi, że potrafi zbudować potrzebną maszynę, a zapłatą będzie zebrana krew."
ns.NarrativeTranslations.pl[8923] = "Kontakt z Anthionem mógłby rzucić światło na kłopoty Mokvara. Próbki jadu są przeznaczone dla Muxa, którego nadprzyrodzone przedsięwzięcie obiecuje sposób na rozmowę ze zmarłymi."
ns.NarrativeTranslations.pl[8924] = "Klimat zmienia konsystencję widmowej materii. Destylator musi zebrać ektoplazmę w Silithus, Winterspring i Eastern Plaguelands, by uzyskać różne potrzebne odmiany."
ns.NarrativeTranslations.pl[8925] = "Ektoplazma potrzebuje stabilnego, przenośnego źródła energii, żeby pozostać aktywna. Rdzeń z magmy, który jest sercem Bokka, mógłby dawać stałe ciepło, jakiego wymaga wykrywacz duchów."
ns.NarrativeTranslations.pl[8926] = "Dostarczając urządzenie zbudowane przez Muxa, wypełniasz swoją część umowy. W nagrodę możesz wymienić pas i rękawice na lepsze, co ma cię zachęcić do dalszej pomocy."
ns.NarrativeTranslations.pl[8927] = "Twoja pomoc zbudowała dość zaufania na kolejną wymianę ekwipunku. Pas i rękawice można ulepszyć już teraz, a pozostałe części zależą od dalszej współpracy."
ns.NarrativeTranslations.pl[8928] = "Energia rdzenia wymaga pręta, który ją przewodzi i się przy tym nie topi. Odpowiednią część sprzedaje imp w Winterspring, a Mux chce, żeby sprzedawca trzymał się ceny, którą wcześniej podał."
ns.NarrativeTranslations.pl[8929] = "Anthion zginął podobno, gdy próbował wejść do Stratholme. Wynalazek goblina wypróbowany na miejscu daje szansę skontaktować się z duchem Anthiona i dowiedzieć się, co wiedział."
ns.NarrativeTranslations.pl[8930] = "Mówi się, że Anthiona zabili nieumarli ze Stratholme niedaleko bram miasta. Użycie tam wykrywacza pokaże, czy maszyna potrafi nawiązać rozmowę ze zmarłymi, której potrzebujesz."
ns.NarrativeTranslations.pl[8931] = "Po dostarczeniu urządzenia zbudowanego przez Muxa przychodzi pora na umówioną nagrodę. Możesz oddać zwykły pas i rękawice, by dostać ulepszenie obiecane za twoją pomoc."
ns.NarrativeTranslations.pl[8932] = "Po dostarczeniu urządzenia zbudowanego przez Muxa przychodzi pora na umówioną nagrodę. Możesz oddać zwykły pas i rękawice, by dostać ulepszenie obiecane za twoją pomoc."
ns.NarrativeTranslations.pl[8933] = "Urządzenie Muxa jest już dostarczone, a twoja pomoc zasługuje na nagrodę. Pancerne rękawice i pas można wymienić na lepsze, co ma cię zachęcić do dalszej pomocy."
ns.NarrativeTranslations.pl[8934] = "Dostarczając urządzenie zbudowane przez Muxa, wypełniasz swoją część umowy. W nagrodę możesz wymienić pas i rękawice na lepsze, co ma cię zachęcić do dalszej pomocy."
ns.NarrativeTranslations.pl[8935] = "Dostarczając urządzenie zbudowane przez Muxa, wypełniasz swoją część umowy. W nagrodę możesz wymienić pas i rękawice na lepsze, co ma cię zachęcić do dalszej pomocy."
ns.NarrativeTranslations.pl[8936] = "Dostarczając urządzenie zbudowane przez Muxa, wypełniasz swoją część umowy. W nagrodę możesz wymienić pas i rękawice na lepsze, co ma cię zachęcić do dalszej pomocy."
ns.NarrativeTranslations.pl[8937] = "Urządzenie Muxa jest już dostarczone, a twoja pomoc zasługuje na nagrodę. Pancerne rękawice i pas można wymienić na lepsze, co ma cię zachęcić do dalszej pomocy."
ns.NarrativeTranslations.pl[8938] = "Twoja pomoc zbudowała dość zaufania na kolejną wymianę ekwipunku. Pas i rękawice można ulepszyć już teraz, a pozostałe części zależą od dalszej współpracy."
ns.NarrativeTranslations.pl[8939] = "Twoja pomoc zbudowała dość zaufania na kolejną wymianę ekwipunku. Pas i rękawice można ulepszyć już teraz, a pozostałe części zależą od dalszej współpracy."
ns.NarrativeTranslations.pl[8940] = "Twoja pomoc zbudowała dość zaufania na kolejną wymianę ekwipunku. Pas i rękawice można ulepszyć już teraz, a pozostałe części zależą od dalszej współpracy."
ns.NarrativeTranslations.pl[8941] = "Twoja pomoc zbudowała dość zaufania na kolejną wymianę ekwipunku. Pas i rękawice można ulepszyć już teraz, a pozostałe części zależą od dalszej współpracy."
ns.NarrativeTranslations.pl[8942] = "Zaufanie zdobyte twoją pomocą zasługuje na konkretną nagrodę. Pas i pancerne rękawice można wymienić już teraz, a dostęp do pozostałych części zależy od tego, czy dalej pomożesz rozwiązać wspólny kłopot."
ns.NarrativeTranslations.pl[8943] = "Twoja pomoc zbudowała dość zaufania na kolejną wymianę ekwipunku. Pas i rękawice można ulepszyć już teraz, a pozostałe części zależą od dalszej współpracy."
ns.NarrativeTranslations.pl[8944] = "Zaufanie zdobyte twoją pomocą zasługuje na konkretną nagrodę. Pas i pancerne rękawice można wymienić już teraz, a dostęp do pozostałych części zależy od tego, czy dalej pomożesz rozwiązać wspólny kłopot."
ns.NarrativeTranslations.pl[8945] = "Anthion ma do przekazania informacje, ale pilniejsza jest niewola jego żony. Prosi cię o dokończenie akcji ratunkowej, która jemu się nie udała, i o uwolnienie Ysidy, którą więżą siły Baron Rivendare'a."
ns.NarrativeTranslations.pl[8946] = "Ysida chce, by Anthion wiedział, że jest bezpieczna, i przestał trzymać się tego świata. Jej wisiorek będzie dowodem dla męża, który zginął, próbując ją uratować."
ns.NarrativeTranslations.pl[8947] = "Theldren dostał kawałek amuletu Valthalaka i gwałtownie odmówił jego zwrotu. Teraz jest gladiatorem, więc trzeba się przygotować, by zmusić go do walki i odzyskać fragment."
ns.NarrativeTranslations.pl[8948] = "Sztandar ma barwy rodu Theldrena, żeby go sprowokować. Falrin zna zaklęcie, które wzmocni tę prowokację i doprowadzi do walki, której gladiator unika."
ns.NarrativeTranslations.pl[8949] = "Falrin zna potrzebne zaklęcie, ale najpierw żąda, by zaspokoić jego nienawiść do ogrów. Ich paciorki posłużą za dowód, zanim zgodzi się porozmawiać o twojej prośbie."
ns.NarrativeTranslations.pl[8950] = "Prowokujące zaklęcie jest dla Falrina proste, ale odczynniki do niego rzadko bywają potrzebne. Żeby nałożyć na sztandar odpowiednią magię, trzeba widmowej esencji, run i odłamków Brilliant Shard."
ns.NarrativeTranslations.pl[8951] = "Podział amuletu Valthalaka uwolnił klątwę związaną z jego duszą. Deliana musi się dowiedzieć, że Bodley może pomóc odnaleźć pozostałe części, które trzeba połączyć, by powstrzymać czar."
ns.NarrativeTranslations.pl[8952] = "Podział amuletu Valthalaka uwolnił klątwę związaną z jego duszą. Deliana musi się dowiedzieć, że Bodley może pomóc odnaleźć pozostałe części, które trzeba połączyć, by powstrzymać czar."
ns.NarrativeTranslations.pl[8953] = "Podział amuletu Valthalaka uwolnił klątwę związaną z jego duszą. Deliana musi się dowiedzieć, że Bodley może pomóc odnaleźć pozostałe części, które trzeba połączyć, by powstrzymać czar."
ns.NarrativeTranslations.pl[8954] = "Podział amuletu Valthalaka uwolnił klątwę związaną z jego duszą. Deliana musi się dowiedzieć, że Bodley może pomóc odnaleźć pozostałe części, które trzeba połączyć, by powstrzymać czar."
ns.NarrativeTranslations.pl[8955] = "Podział amuletu Valthalaka uwolnił klątwę związaną z jego duszą. Deliana musi się dowiedzieć, że Bodley może pomóc odnaleźć pozostałe części, które trzeba połączyć, by powstrzymać czar."
ns.NarrativeTranslations.pl[8956] = "Podział amuletu Valthalaka uwolnił klątwę związaną z jego duszą. Deliana musi się dowiedzieć, że Bodley może pomóc odnaleźć pozostałe części, które trzeba połączyć, by powstrzymać czar."
ns.NarrativeTranslations.pl[8957] = "Dusza Valthalaka została podzielona razem z amuletem, co wywołało klątwę, którą powstrzyma tylko złożenie go na nowo. Mokvar musi się dowiedzieć, że Bodley może pomóc odnaleźć pozostałe części."
ns.NarrativeTranslations.pl[8958] = "Podział amuletu Valthalaka uwolnił klątwę związaną z jego duszą. Deliana musi się dowiedzieć, że Bodley może pomóc odnaleźć pozostałe części, które trzeba połączyć, by powstrzymać czar."
ns.NarrativeTranslations.pl[8959] = "Podział amuletu Valthalaka uwolnił klątwę związaną z jego duszą. Deliana musi się dowiedzieć, że Bodley może pomóc odnaleźć pozostałe części, które trzeba połączyć, by powstrzymać czar."
ns.NarrativeTranslations.pl[8960] = "Bodley ruszył z powrotem do Blackrock Mountain, by wejść do Blackrock Spire, i już nie wrócił. Szukając pozostałych części, warto zabrać wykrywacz duchów na wypadek, gdyby stało się najgorsze."
ns.NarrativeTranslations.pl[8961] = "Żeby przywołać Valthalaka, trzeba odzyskać dwie pozostałe części amuletu. Najpierw, żeby się do tego przygotować, potrzeba specjalnych węgli od trzech władców płomieni i poświęconego paleniska."
ns.NarrativeTranslations.pl[8962] = "Palenisko potrzebuje łącznika dość silnego, by przyciągnąć ducha Mora Grayhoofa. Taką osobistą więź mogą dać szczątki jego przyjaciół druidów, którzy polegli w walce z silithidami."
ns.NarrativeTranslations.pl[8963] = "Przywołanie Isalien wymaga łącznika związanego z jej dzieciństwem w Starbreeze. Relikwia z wioski, skradziona przez olbrzymy z Winterspring, mogłaby powiązać palenisko z jej duchem."
ns.NarrativeTranslations.pl[8964] = "Jarien i Sothos chcieli zostać rycerzami Scarlet. Miecz pretorianów z Tyr's Hand może posłużyć za łącznik, który przyciągnie rodzeństwo przez palenisko."
ns.NarrativeTranslations.pl[8965] = "Kormok uwielbiał przywoływać dusze wygnanych zmarłych z Purgation Isle. Ich prochy mogą być łącznikiem, którego palenisko potrzebuje, by przyciągnąć dawnego towarzysza."
ns.NarrativeTranslations.pl[8966] = "Gdy Mor Grayhoof spadł do dolnej części Blackrock Spire, miał przy sobie niosący zepsucie fragment amuletu Valthalaka. Został pojmany i zamordowany, więc szukać trzeba tam, gdzie skończyła się jego ucieczka."
ns.NarrativeTranslations.pl[8967] = "Isalien zabrała część amuletu do Dire Maul z powodów osobistych i po to, by zbadać jego tajemnice. Wieść, że wpadła w zasadzkę w Shrine of Eldretharr, wskazuje, gdzie szukać zaginionego fragmentu."
ns.NarrativeTranslations.pl[8968] = "Jarien i Sothos zabrali część amuletu, gdy wstępowali do Scarlet Crusade. Zginęli podczas inicjacji, więc żeby odzyskać fragment, trzeba ich szukać tam, gdzie ta próba się nie powiodła."
ns.NarrativeTranslations.pl[8969] = "Kormok zabrał swój fragment amuletu do Scholomance, gdy zajął się nekromancją. Tam zabili go widmowi zabójcy, więc żeby odzyskać fragment, trzeba skontaktować się ze zmarłym dawnym towarzyszem."
ns.NarrativeTranslations.pl[8970] = "Bodley zna się na wróżeniu na tyle, by namierzyć ostatni fragment i towarzyszącego mu ducha. Do tych magicznych poszukiwań potrzebuje wodorostów Bloodkelp od nag z Alcaz."
ns.NarrativeTranslations.pl[8977] = "Mux skończył wykrywacz duchów, którego Deliana potrzebuje, by spróbować skontaktować się z Anthionem. Zanieś urządzenie do Ironforge; inżynier prosi też, by polecać jego usługi potencjalnym klientom."
ns.NarrativeTranslations.pl[8978] = "Mux skończył wykrywacz duchów, którego Mokvar potrzebuje, by spróbować skontaktować się z Anthionem. Zanieś urządzenie do Orgrimmar; inżynier prosi też, by polecać jego usługi potencjalnym klientom."
ns.NarrativeTranslations.pl[8979] = "Fenstad podejrzewa, że modne perfumy mącą w głowach za sprawą alchemii. Próbki zaniesione do Zinge pozwolą sprawdzić, czy to te zapachy tłumaczą dziwne zachowanie, które szerzy się w mieście."
ns.NarrativeTranslations.pl[8980] = "Zinge znalazła w perfumach substancje używane w miksturach kontroli umysłu. Złożoność mieszanki wskazuje na wytrawnego alchemika, więc trzeba zgłosić, jak poważne jest to odkrycie."
ns.NarrativeTranslations.pl[8981] = "Wizyta to okazja, by wręczyć przywódcy podarunek w dowód miłości i podziwu. W tym spotkaniu chodzi o to, by wyrazić te uczucia prezentem, który masz przy sobie."
ns.NarrativeTranslations.pl[8982] = "Katrina kupiła podejrzane perfumy od karczmarza Normana. Rozmawiając z nim, idziesz tropem dostaw i szukasz tego, kto rozprowadza badane zapachy."
ns.NarrativeTranslations.pl[8983] = "Norman mówi, że perfumy sprzedała mu handlarka Mara Rennick. Jej zaplanowana dostawa do krawca to trop w śledztwie w sprawie tego niezwykle popularnego towaru."
ns.NarrativeTranslations.pl[8984] = "Trop perfum prowadzi do Staffrona Lerenta, aptekarza, który pracuje w odosobnieniu za Ravenholdt. Śledztwo na miejscu pozwoli sprawdzić podejrzenie, że jego wyroby osłabiają obronę miasta."
ns.NarrativeTranslations.pl[8985] = "Ostatni fragment jest już namierzony, ale przywołanie Isalien wymaga pamiątki z jej dzieciństwa. Relikwia ze Starbreeze, którą mają olbrzymy, może dać palenisku potrzebną więź."
ns.NarrativeTranslations.pl[8986] = "Samo namierzenie fragmentu nie wystarczy, by przyciągnąć Mora Grayhoofa. Palenisko potrzebuje szczątków jego przyjaciół druidów zabitych przez silithidy, by powstał łącznik z jego duchem."
ns.NarrativeTranslations.pl[8987] = "Palenisko potrzebuje osobistego łącznika, by przywołać Jarien i Sothosa. Oboje chcieli zostać rycerzami Scarlet, więc dobrze nada się miecz pretorianów z Tyr's Hand."
ns.NarrativeTranslations.pl[8988] = "Żeby przyciągnąć Kormoka, trzeba powiązać palenisko z nekromancją, którą się dawniej zajmował. Prochy wygnanych zmarłych z Purgation Isle przywodzą na myśl dusze, które kiedyś uwielbiał przywoływać."
ns.NarrativeTranslations.pl[8989] = "Gdy Mor Grayhoof spadł do dolnej części Blackrock Spire, miał przy sobie niosący zepsucie fragment amuletu Valthalaka. Został pojmany i zamordowany, więc szukać trzeba tam, gdzie skończyła się jego ucieczka."
ns.NarrativeTranslations.pl[8990] = "Isalien zabrała część amuletu do Dire Maul z powodów osobistych i po to, by zbadać jego tajemnice. Wieść, że wpadła w zasadzkę w Shrine of Eldretharr, wskazuje, gdzie szukać zaginionego fragmentu."
ns.NarrativeTranslations.pl[8991] = "Prawa część amuletu została u Jarien i Sothosa, gdy starali się o przyjęcie do Scarlet Crusade. Zginęli podczas inicjacji, a to wskazuje, gdzie dalej szukać tego fragmentu."
ns.NarrativeTranslations.pl[8992] = "Kormok miał przy sobie część amuletu, gdy widmowi zabójcy zabili go w Scholomance. Ponowne przywołanie Kormoka ma pomóc odzyskać fragment, który zabrał, odchodząc z drużyny."
ns.NarrativeTranslations.pl[8993] = "Wizyta to okazja, by wręczyć przywódcy podarunek w dowód miłości i podziwu. W tym spotkaniu chodzi o to, by wyrazić te uczucia prezentem, który masz przy sobie."
ns.NarrativeTranslations.pl[8994] = "Palenisko potrzebuje jeszcze śladowych ilości metali z karwaszy orków z Blackrock Spire. Razem z miksturą Flask of Supreme Power pozwolą je dostroić do przywołania Valthalaka."
ns.NarrativeTranslations.pl[8995] = "Valthalaka trzeba przywołać tam, gdzie mieszkał, i pokonać, gdy odzyska cielesną postać. Potem trzeba użyć amuletu na jego ciele, by spróbować połączyć na nowo skradzione części jego ducha."
ns.NarrativeTranslations.pl[8996] = "Valthalak przyznaje, że wróciła do niego reszta skradzionego ducha. Pozwala ci przekazać jego dawnym wrogom, że są bezpieczni, choć z jego ostrzeżenia wynika, że to bezpieczeństwo tylko na jakiś czas."
ns.NarrativeTranslations.pl[8997] = "Po twojej pomocy Bodley żegna się i prosi, by wrócić do Deliany w Ironforge. Gdy opowiesz, co się wydarzyło, wyczekiwane wieści dotrą do tej, która zaczęła całe przedsięwzięcie."
ns.NarrativeTranslations.pl[8998] = "Z Bodleyem będzie można jeszcze porozmawiać, ale relacja musi trafić do Mokvara. Wracając do Orgrimmar, przekażesz mu, co się działo podczas prób rozwiązania jego kłopotu."
ns.NarrativeTranslations.pl[8999] = "Twoja pomoc rozwiała obawy tych, którzy wpadli w te tarapaty. Wysłuchali opowieści o twoich staraniach i w podzięce dają ci nagrodę."
ns.NarrativeTranslations.pl[9000] = "Twoja pomoc rozwiała obawy tych, którzy wpadli w te tarapaty. Wysłuchali opowieści o twoich staraniach i w podzięce dają ci nagrodę."
ns.NarrativeTranslations.pl[9001] = "Twoja pomoc rozwiała obawy tych, którzy wpadli w te tarapaty. Wysłuchali opowieści o twoich staraniach i w podzięce dają ci nagrodę."
ns.NarrativeTranslations.pl[9002] = "Twoja pomoc rozwiała obawy tych, którzy wpadli w te tarapaty. Wysłuchali opowieści o twoich staraniach i w podzięce dają ci nagrodę."
ns.NarrativeTranslations.pl[9003] = "Twoja pomoc rozwiała obawy tych, którzy wpadli w te tarapaty. Wysłuchali opowieści o twoich staraniach i w podzięce dają ci nagrodę."
ns.NarrativeTranslations.pl[9004] = "Twoja pomoc rozwiała obawy tych, którzy wpadli w te tarapaty. Wysłuchali opowieści o twoich staraniach i w podzięce dają ci nagrodę."
ns.NarrativeTranslations.pl[9005] = "Twoja pomoc rozwiała obawy tych, którzy wpadli w te tarapaty. Wysłuchali opowieści o twoich staraniach i w podzięce dają ci nagrodę."
ns.NarrativeTranslations.pl[9006] = "Twoja pomoc rozwiała obawy tych, którzy wpadli w te tarapaty. Wysłuchali opowieści o twoich staraniach i w podzięce dają ci nagrodę."
ns.NarrativeTranslations.pl[9007] = "Opowieść o twojej pomocy pozwala zainteresowanym zostawić dawne błędy za sobą. W podzięce dają ci też nagrodę za to, że dzięki tobie nie muszą już ponosić ich skutków."
ns.NarrativeTranslations.pl[9008] = "Opowieść o twojej pomocy pozwala zainteresowanym zostawić dawne błędy za sobą. W podzięce dają ci też nagrodę za to, że dzięki tobie nie muszą już ponosić ich skutków."
